import{z as d,x as n,o as s,c as i,q as A,j as o,D as a,d as e,s as B,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"压缩列存","description":"","frontmatter":{"title":"压缩列存","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/st-compressed-columnar.md","filePath":"cs/st-compressed-columnar.md","lastUpdated":1791063341000}'),C={name:"cs/st-compressed-columnar.md"};function D(c,E,p,m,u,F){const r=n("Mermaid");return s(),i("div",null,[E[2]||(E[2]=A('<h1 id="压缩列存" tabindex="-1">压缩列存 <a class="header-anchor" href="#压缩列存" aria-label="Permalink to &quot;压缩列存&quot;">​</a></h1><div class="epigraph"><p>编码与压缩是两层而非一个旋钮：编码把列变成小整数与重复结构，通用压缩再压一遍字节。压缩比与扫描速度是联合设计，不是分开调的两个参数。</p><footer>—— 据 Abadi, Madden and Ferreira, CIDR 2006；Zukowski et al., CIDR 2005；Apache Parquet 文档整理</footer></div><p><a href="/cs/st-parquet-anatomy">上一课</a>解剖到列块为止，列块内部是编码与压缩的两层栈。主干已钉过 <a href="/cs/column-compression">列压缩：字典、RLE、位打包</a> 的三种语义编码如何服务扫描与过滤、编码选择看 NDV 与有序度。本课不再定义编码，问三层更深的账：语义编码与字节级压缩怎么叠、排序怎么变成压缩、查询怎么在码域完成而迟迟不解码。后课默认：列块的编码-压缩栈是读写合同的最后一段，选择它就是选择扫描的执行方式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>第一个坑是把两层当一层。语义编码（字典、RLE、delta、frame-of-reference、位打包）可逆且保持列语义，把高熵字符串换成小整数、把重复暴露成游程；字节级 codec（snappy、lz4、zstd）对页再做一遍熵压缩。问「zstd 是不是比 RLE 好」是错的问题——它们作用在不同层，混用判断会让引擎既丢掉码域执行，又拿到更慢的解码。<span class="marginnote">常见误区：初学者容易拿压缩比单挑——「zstd 能压 5 倍，RLE 才 3 倍，选 zstd」。实际上 codec 只把字节压小，不提供码域过滤；比大小之前先问执行器还要不要在压缩态上做谓词，答案往往倒过来。</span>第二个坑是解压吞吐：单核 lz4 解压以 GB/s 计，zstd 以数百 MB/s 计，而内存带宽十 GB/s 量级——编码选错，扫描瓶颈就从 I/O 挪到解压，压缩比再漂亮也是负资产。第三个坑是乱序：同一列，有序时 RLE 收益巨大，乱序时字典或许尚可，硬上 RLE 只是白写白读。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>决策按下游算子倒推。先看谓词与聚合：过滤条件与分组键若能落在字典码上，过滤与聚合就成了整数运算，原值只在投影出口解码，且只解码命中行——这是延迟物化的执行形态。<span class="marginnote">术语翻译：码域执行就是过滤与聚合直接在压缩后的整数编码上做算术，不把字典码翻回原字符串；只有最终要输出的列才解码，且只解命中的那些行。</span>再看分布：低基数高重复选字典加 RLE，单调列选 delta 加 frame-of-reference，近随机唯一列只剩位打包加字节压缩。然后定排序：复合排序键把常一起过滤的列放前面，前列等值时后列局部有序，RLE 与字典的收益从前列传导到后列；跨行组用区间聚簇、行组内排序，两段配合也喂饱了上一课的页级统计。最后叠 codec：语义编码已把结构暴露，页级压缩常取中低级别——zstd 的解压速度对压缩级别不敏感，编码端才敏感，扫描型负载吃亏在哪一端要先测再定。</p>',7)),(s(),o(l,null,{default:a(()=>[B(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20COL%5B%22%E5%8E%9F%E5%A7%8B%E5%88%97%22%5D%20--%3E%20ENC%7B%22%E7%BC%96%E7%A0%81%E9%80%89%E6%8B%A9%EF%BC%9ANDV%20%E4%B8%8E%E6%9C%89%E5%BA%8F%E5%BA%A6%22%7D%0A%20%20ENC%20--%3E%7C%22%E4%BD%8E%E5%9F%BA%E6%95%B0%E9%AB%98%E9%87%8D%E5%A4%8D%22%7C%20DICT%5B%22%E5%AD%97%E5%85%B8%20%2B%20RLE%22%5D%0A%20%20ENC%20--%3E%7C%22%E5%8D%95%E8%B0%83%22%7C%20DELTA%5B%22delta%20%2B%20%E4%BD%8D%E6%89%93%E5%8C%85%22%5D%0A%20%20ENC%20--%3E%7C%22%E8%BF%91%E9%9A%8F%E6%9C%BA%E5%94%AF%E4%B8%80%22%7C%20RAW%5B%22%E4%BD%8D%E6%89%93%E5%8C%85%22%5D%0A%20%20DICT%20--%3E%20CODEC%5B%22%E9%A1%B5%E7%BA%A7%20codec%EF%BC%9Alz4%2Fzstd%22%5D%0A%20%20DELTA%20--%3E%20CODEC%0A%20%20RAW%20--%3E%20CODEC%0A%20%20CODEC%20--%3E%20DISK%5B%22%E5%88%97%E5%9D%97%E8%90%BD%E7%9B%98%22%5D%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20DOM%7B%22%E8%83%BD%E5%90%A6%E7%A0%81%E5%9F%9F%E6%89%A7%E8%A1%8C%EF%BC%9F%22%7D%0A%20%20DOM%20--%3E%7C%22%E6%98%AF%22%7C%20VC%5B%22%E7%A0%81%E5%9F%9F%E8%BF%87%E6%BB%A4%2F%E8%81%9A%E5%90%88%EF%BC%8C%E5%91%BD%E4%B8%AD%E6%89%8D%E8%A7%A3%E7%A0%81%22%5D%0A%20%20DOM%20--%3E%7C%22%E5%90%A6%22%7C%20DEC%5B%22%E8%A7%A3%E7%A0%81%E5%90%8E%E6%8C%89%E8%A1%8C%E5%A4%84%E7%90%86%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,[e("两层栈有效的机制在于熵的搬运：字典把随机字符串的熵集中到码本、把列体变成低熵整数流；codec 恰好吃低熵与长重复。跳过语义编码直接压原始字节也能压，但码域过滤与延迟解码随之消失——执行器从此必须解压才能判断。所以压缩比与执行是联合设计：一个数列若能用 1–2 字节的位打包表示，多数谓词不必解压就能评估；用 zstd 硬压到类似大小，则每个谓词都欠一次整页解压。排序是唯一的免费午餐：它同时改善编码收益、页级统计与区间跳过，代价只在写入端付一次。"),t("span",{class:"marginnote"},"直觉类比：排序像把图书馆按主题归架——同一主题的书连成一片，检索时整架整架地跳过；乱序堆放时每一本都得翻封面。排序把「重复」变成「连续」，RLE 的游程才有得数。")],-1)),(s(),o(l,null,{default:a(()=>[B(r,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20SK%5B%22%E5%A4%8D%E5%90%88%E6%8E%92%E5%BA%8F%E9%94%AE%EF%BC%9Acity%2C%20date%22%5D%20--%3E%20S1%5B%22%E5%89%8D%E5%88%97%20city%20%E5%85%A8%E5%B1%80%E6%9C%89%E5%BA%8F%22%5D%0A%20%20S1%20--%3E%20R1%5B%22city%20%E6%B8%B8%E7%A8%8B%E9%95%BF%EF%BC%8CRLE%20%E5%A4%A7%E8%B5%9A%22%5D%0A%20%20S1%20--%3E%20LOC%5B%22city%20%E7%AD%89%E5%80%BC%E5%9D%97%E5%86%85%20date%20%E5%B1%80%E9%83%A8%E6%9C%89%E5%BA%8F%22%5D%0A%20%20LOC%20--%3E%20R2%5B%22date%20%E5%9D%97%E5%86%85%E6%B8%B8%E7%A8%8B%EF%BC%8CRLE%20%E5%B0%8F%E8%B5%9A%22%5D%0A%20%20R1%20--%3E%20ST%5B%22%E9%A1%B5%E7%BA%A7%20min%2Fmax%20%E5%8C%BA%E9%97%B4%E6%94%B6%E7%AA%84%22%5D%0A%20%20R2%20--%3E%20ST%0A%20%20ST%20--%3E%20SKIP%5B%22%E6%89%AB%E6%8F%8F%E8%B7%B3%E8%BF%87%E6%97%A0%E5%85%B3%E8%A1%8C%E7%BB%84%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=A('<p><span class="marginnote">数字锚点：4 字节时间戳列经 delta 加 frame-of-reference 常可压到 1–2 字节每值，且等值过滤在打包域即可完成；直接 zstd 压原始字节虽可达相近大小，但每个谓词都要付整页解压。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲三种语义编码的定义（<a href="/cs/column-compression">列压缩课</a>是前置），不进向量化执行引擎的完整展开，也不比 Parquet 与 ORC 的编码开关细节。压缩域执行到此只到「码域谓词与延迟物化」，join 与聚合在压缩域的进一步展开不属本课。后课默认：列块的编码-压缩栈已定，扫描的代价模型按「码域完成多少」重新校准。下一课把视野拉回整条存储栈：各层缓存怎么拼成一张层次图。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>编码与压缩是两层：语义编码保可逆与列语义，codec 对页再做熵压缩，不可混为一谈。</li><li>解码吞吐是预算：编码选错，扫描瓶颈从 I/O 挪到解压。</li><li>编码按下游算子倒推：谓词能落码域，过滤与聚合就是整数运算，命中才解码。</li><li>排序是免费午餐：前列等值让后列局部有序，编码、统计、跳过三处同赚。</li><li>出处：Abadi, Madden and Ferreira, CIDR 2006；Zukowski et al., CIDR 2005；Apache Parquet 文档。</li></ul>',5))])}const _=d(C,[["render",D]]);export{h as __pageData,_ as default};
